// ---------------------------------------------------------------
// Enriquecimiento del lead con el catalogo real de Shopify.
// Entrada esperada en el webhook (JSON o form):
//   name        -> nombre del contacto
//   phone       -> telefono
//   ad_name     -> nombre del anuncio de Meta (ej: "HIPERCALORICO VITAMIN HORSE 3KG [VIDEO]")
//   message     -> primer mensaje del cliente (el prellenado del anuncio)
// ---------------------------------------------------------------

const lead = $('Entrada de Lead').first().json;
const body = lead.body || lead.query || lead;

const productos = ($('Catalogo Shopify').first().json.products) || [];

// --- normalizacion ---
const limpiar = (s) => (s || '')
  .toString()
  .toUpperCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^A-Z0-9 ]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

let telefono = (body.phone || '').toString().replace(/\D/g, '');
if (telefono && !telefono.startsWith('598') && !telefono.startsWith('55')) {
  telefono = '598' + telefono.replace(/^0+/, '');
}

const nombre = (body.name || '').toString().trim() || 'Lead sin nombre';
const textoAnuncio = limpiar(body.ad_name);
const textoMensaje = limpiar(body.message);
const pista = (textoAnuncio + ' ' + textoMensaje).trim();

// --- categorizacion (mismas reglas que el catalogo del agente) ---
function categoria(n) {
  const u = limpiar(n);
  if (/^KIT |KIT |COMBO /.test(u)) return 'kits y combos';
  if (/CREATIN/.test(u)) return 'creatina';
  if (/WHEY|PROTEIN|CASEIN|ALBUMIN|ISOLAD|ISOLATE|CARNIBOL|MASTODON|CREAMASS|HIPERCAL|HYPER|GAINER|MASS/.test(u)) return 'proteinas';
  if (/BCAA|GLUTAMIN|ARGININ|BETA ALANIN|EAA|HMB|AMINO|TAURIN|CARNITIN/.test(u)) return 'aminoacidos';
  if (/THERMO|TERMO|ABDOMEN|LIPO|BURN|KIMERA|CLEMBUTER|DIMETHYL/.test(u)) return 'termogenicos';
  if (/PRE TREINO|PRE WORKOUT|PRE ENTRENO|WORKOUT|ENERGY|NITRATO|PUMP|HAZE|DILATED|TESTO|BOPE|FIRE GUN|HUGER|EVORA|BOOSTER/.test(u)) return 'pre-entreno';
  if (/HYDRO|RECHARGE|SALT|ISOTON|ELECTROL/.test(u)) return 'hidratacion';
  if (/VITAMIN|FISH OIL|OMEGA|ZMA|MULTI|MAGNESIO|ZINC|MELATONIN/.test(u)) return 'vitaminas y salud';
  if (/COLAGEN|COLLAGEN/.test(u)) return 'colageno';
  if (/BARRA|BAR |PROTOBAR|CRISP|PACOCA|ALFAJOR|COOKIE|CHIPS/.test(u)) return 'barras y snacks';
  if (/PEANUT|AMENDOIM/.test(u)) return 'pasta de mani';
  if (/MALTO|DEXTRIN|WAXY|PALATINOSE|CARBO/.test(u)) return 'carbohidratos';
  return 'otros';
}

const OBJETIVO = {
  'proteinas': 'ganar masa muscular',
  'creatina': 'ganar masa muscular',
  'carbohidratos': 'ganar masa muscular',
  'aminoacidos': 'ganar masa muscular',
  'kits y combos': 'ganar masa muscular',
  'termogenicos': 'bajar de peso',
  'pre-entreno': 'rendimiento',
  'hidratacion': 'rendimiento',
  'vitaminas y salud': 'salud general',
  'colageno': 'salud general'
};

// --- matching: cuantas palabras del anuncio aparecen en el nombre del producto ---
const palabras = pista.split(' ').filter(p => p.length > 2 && !['PARA','CON','LOS','LAS','DEL','QUIERO','COMPRAR','HOLA','VIDEO','IMG','MENSAJES'].includes(p));

let mejor = null;
let mejorPuntaje = 0;
for (const p of productos) {
  const nom = limpiar(p.title);
  let puntaje = 0;
  for (const w of palabras) { if (nom.includes(w)) puntaje++; }
  if (puntaje > mejorPuntaje) { mejorPuntaje = puntaje; mejor = p; }
}

// se exige un minimo de coincidencia para no inventar un match
const identificado = mejor !== null && mejorPuntaje >= 2;
const v = identificado ? (mejor.variants[0] || {}) : {};
const cat = identificado ? categoria(mejor.title) : '';

// --- alternativas de la misma categoria (para que el vendedor/agente tenga con que cruzar) ---
let alternativas = [];
if (identificado) {
  alternativas = productos
    .filter(p => p.handle !== mejor.handle && categoria(p.title) === cat)
    .slice(0, 3)
    .map(p => `${p.title} ($${(p.variants[0] || {}).price || '?'})`);
}

// --- prioridad ---
// caliente: el anuncio identifica un producto concreto -> el lead ya sabe que quiere
// tibio: hay pista de categoria pero no de producto
// frio: no hay nada, hay que diagnosticar desde cero
let prioridad = 'frio';
if (identificado) prioridad = 'caliente';
else if (pista.length > 0) prioridad = 'tibio';

return [{
  json: {
    name: nombre,
    phone: telefono,
    prioridad,
    producto_interes: identificado ? mejor.title : '',
    categoria_interes: cat,
    objetivo_lead: OBJETIVO[cat] || '',
    precio_uyu: v.price || '',
    link_producto: identificado ? ('https://fitnessuplementos.com/products/' + mejor.handle) : '',
    sku: v.sku || '',
    disponible_web: identificado ? (v.available ? 'si' : 'no') : '',
    alternativas: alternativas.join(' | '),
    anuncio_origen: body.ad_name || '',
    primer_mensaje: body.message || '',
    confianza_match: mejorPuntaje,
    procesado_en: new Date().toISOString()
  }
}];
